/**
 * What the plans' refund policy gives back, and never more than was paid.
 * 232 [CA1] unit 6; the button that uses it is 305 [SY1].
 *
 * The policy is app/refunds/page.tsx, sections 2, 3 and 5:
 *   - the first payment on an account, refunded in full when asked within
 *     REFUND_DAYS of it ("guarantee");
 *   - a yearly payment, at any time, less the months that have started at the
 *     plan's monthly price and less Stripe's card fee on that payment, which
 *     Stripe does not give back ("unstarted_months"); a first yearly payment
 *     asked about within REFUND_DAYS takes the guarantee instead;
 *   - nothing else: a monthly renewal, a switch charge, any later charge.
 *
 * Pure: it reads the charge as Stripe reports it and answers how many cents a
 * refund may be, why there is none, or that it cannot tell yet. It calls
 * nothing. Rules the rest of the code relies on:
 *   - the amount is what the charge captured (Stripe's
 *     `charge.amount_captured` on a `succeeded` charge), already net of
 *     coupons and discounts; the list price is never used for the guarantee;
 *     a charge that did not succeed gives nothing back;
 *   - only an invoice paid wholly by this one charge is decided: when a
 *     customer balance (credit) paid part of it, the policy's "what you
 *     paid" is not this charge alone, so the answer is "unknown";
 *   - only the subscription's own charges (Stripe `billing_reason`
 *     `subscription_create` or `subscription_cycle`) get the yearly months;
 *     a switch charge (`subscription_update`) on a monthly plan gets nothing,
 *     section 5, and on a yearly plan is "unknown" (it may be the yearly
 *     payment itself), unless it is the first charge on the account asked about
 *     inside the window, which section 2 covers whatever it was for;
 *   - what was already refunded (`charge.amount_refunded`) is taken off, so
 *     the total ever given back for one charge never passes what the policy
 *     gives, nor what the charge took. Two callers that read the same
 *     `amount_refunded` at once would each get the same answer, so the
 *     refund write (305 [SY1]) must carry a Stripe idempotency key and a lock;
 *   - Stripe's fee is kept only when it is in the charge's currency (the
 *     balance transaction's currency is the account's settlement currency,
 *     which may differ); otherwise "unknown";
 *   - a dispute (Stripe's dispute `status`): open, or a status this code does
 *     not know, means no refund now (the bank may return it); `lost` and
 *     `prevented` for the whole charge mean the money went back that way
 *     already, and for part of it "unknown" (the rest is not decided here); `won` and
 *     `warning_closed` let the policy apply again (statuses read on
 *     docs.stripe.com/api/disputes/object, 31/10/2026);
 *   - tax shown on top comes back with the part refunded, in proportion,
 *     rounded down; for the guarantee the whole payment, tax included;
 *   - anything that is not a whole, non-negative number of cents, or a
 *     currency the monthly price is not in, is "unknown", never a guess and
 *     never zero dressed up as "nothing is owed".
 */
import { REFUND_DAYS } from "@/lib/plan";

const DAY_SECONDS = 86_400;

export type PlanRefundCharge = {
  /** Stripe's lowercase three-letter code. */
  currency: string;
  /** Whether Stripe reports the charge `succeeded`. */
  succeeded: boolean;
  /** What the charge captured, in the smallest unit: `charge.amount_captured`. */
  amountCents: number;
  /** The total of the invoice this charge paid (`invoice.total`); equal to amountCents unless a balance paid part. */
  invoiceTotalCents: number;
  /** Stripe's `invoice.billing_reason` for that invoice. */
  billingReason: string;
  /** What has been refunded from it already: `charge.amount_refunded`. */
  refundedCents: number;
  /** Tax on the invoice this charge paid, included in amountCents. */
  taxCents: number;
  /** Stripe's fee on the charge (its balance transaction), or null if not read. */
  feeCents: number | null;
  /** The balance transaction's currency, which the fee is in. */
  feeCurrency: string | null;
  /** When it was paid, in seconds. */
  paidAtSeconds: number;
  /** The status of a dispute on it, or null when there is none. */
  disputeStatus: string | null;
  /** The dispute's amount (`dispute.amount`), or null when there is none. */
  disputedCents: number | null;
};

export type PlanRefundInput = {
  cycle: "month" | "year";
  /** Whether this is the first charge on the account (decided by the caller). */
  firstPayment: boolean;
  /** Start of the billing period this charge paid for, in seconds. */
  periodStartSeconds: number;
  /** The plan's monthly price when this yearly payment was made, same currency; null if not known. */
  monthlyCents: number | null;
  /** The currency of monthlyCents; "usd" when absent, as every plan price is. */
  monthlyCurrency?: string;
  nowSeconds: number;
  charge: PlanRefundCharge;
};

export type PlanRefund =
  | { kind: "guarantee"; cents: number }
  | { kind: "unstarted_months"; cents: number; monthsKept: number }
  | { kind: "none"; reason: "not_paid" | "nothing_paid" | "dispute_open" | "dispute_returned" | "already_refunded" | "outside_window" | "renewal" | "switch_charge" | "months_used" | "fee_kept" }
  | { kind: "unknown"; reason: "unreadable" | "split_payment" | "switch_yearly" | "dispute_partial" | "billing_reason" | "fee_unread" | "monthly_price_unknown" | "currency" };

const RETURNED = new Set(["lost", "prevented"]);
const SETTLED = new Set(["won", "warning_closed"]);
const OWN_CHARGE = new Set(["subscription_create", "subscription_cycle"]);
const SWITCH_CHARGE = new Set(["subscription_update"]);

function cents(n: unknown): n is number {
  return typeof n === "number" && Number.isSafeInteger(n) && n >= 0;
}

/**
 * A date some whole months after `startSeconds`, the way Stripe moves a
 * billing anchor: the same day and time, or the month's last day when it has
 * no such day (an anchor on the 31st bills on Feb 28). UTC throughout.
 */
export function addMonthsLikeStripe(startSeconds: number, months: number): number {
  const d = new Date(startSeconds * 1000);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth() + months;
  const last = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
  const day = Math.min(d.getUTCDate(), last);
  return Date.UTC(y, m, day, d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds()) / 1000;
}

/** How many of a yearly period's twelve months have started by `nowSeconds` (0 to 12). */
export function monthsStarted(periodStartSeconds: number, nowSeconds: number): number {
  let n = 0;
  for (let k = 0; k < 12; k += 1) {
    if (addMonthsLikeStripe(periodStartSeconds, k) <= nowSeconds) n += 1;
    else break;
  }
  return n;
}

export function planRefund(input: PlanRefundInput): PlanRefund {
  const c = input.charge;
  if (!cents(c.amountCents) || !cents(c.refundedCents) || !cents(c.taxCents) || !cents(c.invoiceTotalCents) || c.taxCents > c.invoiceTotalCents) return { kind: "unknown", reason: "unreadable" };
  if (c.feeCents !== null && !cents(c.feeCents)) return { kind: "unknown", reason: "unreadable" };
  if (c.disputedCents !== null && !cents(c.disputedCents)) return { kind: "unknown", reason: "unreadable" };
  if (typeof c.billingReason !== "string" || typeof c.succeeded !== "boolean") return { kind: "unknown", reason: "unreadable" };
  if (!Number.isFinite(c.paidAtSeconds) || !Number.isFinite(input.nowSeconds) || !Number.isFinite(input.periodStartSeconds)) return { kind: "unknown", reason: "unreadable" };

  if (!c.succeeded) return { kind: "none", reason: "not_paid" };
  if (c.invoiceTotalCents !== c.amountCents) return { kind: "unknown", reason: "split_payment" };
  if (c.amountCents === 0) return { kind: "none", reason: "nothing_paid" };

  if (c.disputeStatus !== null) {
    if (RETURNED.has(c.disputeStatus)) {
      if (c.disputedCents !== null && c.disputedCents < c.amountCents) return { kind: "unknown", reason: "dispute_partial" };
      return { kind: "none", reason: "dispute_returned" };
    }
    if (!SETTLED.has(c.disputeStatus)) return { kind: "none", reason: "dispute_open" };
  }

  const left = c.amountCents - c.refundedCents;
  if (left <= 0) return { kind: "none", reason: "already_refunded" };

  const inWindow = input.nowSeconds <= c.paidAtSeconds + REFUND_DAYS * DAY_SECONDS;
  if (input.firstPayment && inWindow) return { kind: "guarantee", cents: left };

  if (SWITCH_CHARGE.has(c.billingReason)) {
    // A switch onto (or within) a yearly plan may itself be the yearly
    // payment, whose unstarted months section 5 says are always refunded;
    // telling that apart from a proration-only charge needs the invoice's
    // lines, so it is not decided here.
    return input.cycle === "year" ? { kind: "unknown", reason: "switch_yearly" } : { kind: "none", reason: "switch_charge" };
  }
  if (!OWN_CHARGE.has(c.billingReason)) return { kind: "unknown", reason: "billing_reason" };
  if (input.cycle !== "year") return { kind: "none", reason: input.firstPayment ? "outside_window" : "renewal" };

  if (input.monthlyCents === null) return { kind: "unknown", reason: "monthly_price_unknown" };
  if (!cents(input.monthlyCents)) return { kind: "unknown", reason: "unreadable" };
  if (c.currency !== (input.monthlyCurrency ?? "usd")) return { kind: "unknown", reason: "currency" };
  if (c.feeCents === null) return { kind: "unknown", reason: "fee_unread" };
  if (c.feeCurrency !== c.currency) return { kind: "unknown", reason: "currency" };

  const kept = monthsStarted(input.periodStartSeconds, input.nowSeconds);
  const preTaxPaid = c.amountCents - c.taxCents;
  const keptCents = Math.min(preTaxPaid, kept * input.monthlyCents);
  const preTaxBack = preTaxPaid - keptCents;
  const taxBack = preTaxPaid > 0 ? Math.floor((c.taxCents * preTaxBack) / preTaxPaid) : 0;
  if (preTaxBack <= 0) return { kind: "none", reason: "months_used" };
  const policy = preTaxBack + taxBack - c.feeCents;
  if (policy <= 0) return { kind: "none", reason: "fee_kept" };
  const now = Math.min(policy - c.refundedCents, left);
  if (now <= 0) return { kind: "none", reason: "already_refunded" };
  return { kind: "unstarted_months", cents: now, monthsKept: kept };
}

files.lib/checkup-rules.ts:
/**
 * "Something's not working": what the studio's checkup says about each part
 * of a store (491 [PP2], unit 1; added 1 November 2026).
 *
 * Each check is worked out here from what a reader already in the code found
 * (lib/stripe-connect.ts readAccount, lib/domains.ts domainStatus,
 * lib/mail-health.ts pauseForSending, lib/checkout-trouble.ts readTrouble),
 * with no model and nothing guessed:
 *
 *   ok           the reader answered and found nothing wrong;
 *   problem      it found something: the cause in plain words, what happens
 *                if it is left, and the fix (a page in the studio, or the
 *                exact place outside it when only the creator can fix it);
 *   not-checked  the reader could not answer, or there is no reader yet.
 *                Never shown as fine.
 *
 * A part the store does not use (no domain of its own) is left out rather
 * than said to be fine. The page that shows these is app/studio/checkup
 * (unit 2), read by lib/checkup.ts; the readers for the plan's limits and
 * for open disputes are still to come, and until then those two are always
 * "not checked".
 *
 * Browser-safe: plain data and pure functions.
 */

import { API_SALES_UNITS, API_WRITE_UNITS, type AllowanceKind, KIND_WORDS, askedCeiling } from "@/lib/store-allowance-rules";
import { STUDIO_PAGE_UNITS } from "@/lib/studio-allowance-rules";

export type CheckState = "ok" | "problem" | "not-checked";
export type CheckId = "stripe" | "domain" | "email" | "checkout" | "limits" | "disputes";

/** Where the fix is: a page of the studio, or a place only the creator can reach. */
export type CheckFix = { kind: "studio"; href: string; label: string } | { kind: "outside"; where: string };

export type Check = {
  id: CheckId;
  /** What is checked, as a heading. */
  title: string;
  state: CheckState;
  /** One sentence: what was found, or why it could not be checked. */
  found: string;
  /** For a problem: what happens if it is left. */
  ifLeft?: string;
  /** For a problem: how to put it right. */
  fix?: CheckFix;
};

const STRIPE_FIX: CheckFix = { kind: "studio", href: "/studio#stripe", label: "Open your Stripe connection" };

/** The creator's Stripe account, as Stripe says it is right now; null when Stripe could not be asked. */
export function stripeCheck(connected: boolean, account: { chargesEnabled: boolean; detailsSubmitted: boolean } | null): Check {
  const title = "Payments";
  if (!connected) {
    return { id: "stripe", title, state: "problem", found: "Your store is not connected to a Stripe account.", ifLeft: "Nobody can buy anything from your store.", fix: STRIPE_FIX };
  }
  if (!account) return { id: "stripe", title, state: "not-checked", found: "We could not ask Stripe about your account just now. Try again in a few minutes." };
  if (!account.detailsSubmitted && !account.chargesEnabled) {
    return {
      id: "stripe",
      title,
      state: "problem",
      found: "Stripe has turned off card payments on your account, and the date to send details about you or your business has passed.",
      ifLeft: "Buyers cannot pay by card in your store until Stripe has what it asks for.",
      fix: { kind: "outside", where: "In your Stripe dashboard, look for the notice asking for information, and send what it asks for." },
    };
  }
  if (!account.detailsSubmitted) {
    return {
      id: "stripe",
      title,
      state: "problem",
      found: "Stripe is waiting for details about you or your business, and the date to send them has passed.",
      ifLeft: "Stripe can stop your payments or your payouts until it has them.",
      fix: { kind: "outside", where: "In your Stripe dashboard, look for the notice asking for information, and send what it asks for." },
    };
  }
  if (!account.chargesEnabled) {
    return {
      id: "stripe",
      title,
      state: "problem",
      found: "Stripe has not turned on card payments for your account.",
      ifLeft: "Buyers cannot pay by card in your store.",
      fix: STRIPE_FIX,
    };
  }
  return { id: "stripe", title, state: "ok", found: "Stripe says your account can take card payments." };
}

const DOMAIN_FIX: CheckFix = { kind: "studio", href: "/studio#domain", label: "Open your domain settings" };

/**
 * The store's own domain, as Vercel sees it (lib/domains.ts, domainCheckup).
 * Left out (null) when the store has none; not checked when Vercel could not
 * be asked; "gone" when Vercel says it is no longer set to serve the store;
 * "resting" when the store is not on Pro, so its pages send visitors to the
 * marktmorgen.com address whatever the records say (Vercel is not asked).
 */
export function domainCheck(domain: string | null, status: { live: boolean; records: unknown[] } | "gone" | "resting" | null | undefined): Check | null {
  if (!domain) return null;
  const title = "Your domain";
  if (status === "resting") {
    return {
      id: "domain",
      title,
      state: "problem",
      found: `${domain} is resting, because your store is not on Pro right now.`,
      ifLeft: `People who type ${domain} are sent to your marktmorgen.com address instead.`,
      fix: DOMAIN_FIX,
    };
  }
  if (!status) return { id: "domain", title, state: "not-checked", found: `We could not check ${domain} just now. Try again in a few minutes.` };
  if (status === "gone") {
    return {
      id: "domain",
      title,
      state: "problem",
      found: `${domain} is no longer set up to serve your store on our side. To use it again, remove it in your domain settings and add it again.`,
      ifLeft: `People who type ${domain} do not reach your store. Your marktmorgen.com address still works.`,
      fix: DOMAIN_FIX,
    };
  }
  // live is Vercel's own verdict on the records (lib/domains.ts); the certificate is not part of it, so it is not claimed.
  if (status.live) return { id: "domain", title, state: "ok", found: `${domain} is set up to show your store.` };
  return {
    id: "domain",
    title,
    state: "problem",
    found: `${domain} does not show your store yet: its DNS records are missing or wrong.`,
    ifLeft: `People who type ${domain} do not reach your store. Your marktmorgen.com address still works.`,
    fix: { kind: "studio", href: "/studio#domain", label: "See the records to add" },
  };
}

/**
 * Email to the creator's list: paused for bounces or spam reports, or not,
 * as pauseForSending (lib/mail-health.ts) reads it; undefined when it could
 * not be read. Its `until` is in seconds, as that file keeps it.
 */
export function emailCheck(pause: { reason: "bounces" | "complaints"; until: number } | null | undefined, now = Date.now()): Check {
  const title = "Email to your list";
  if (pause === undefined) return { id: "email", title, state: "not-checked", found: "We could not read whether your list's email is paused just now. Try again in a few minutes." };
  if (pause === null || pause.until * 1000 <= now) return { id: "email", title, state: "ok", found: "Email to your list is not paused." };
  const day = new Date(pause.until * 1000).toLocaleDateString("en-US", { month: "long", day: "numeric", timeZone: "UTC" });
  return {
    id: "email",
    title,
    state: "problem",
    found:
      pause.reason === "bounces"
        ? "Email to your list is paused: too many of your emails went to addresses that do not exist."
        : "Email to your list is paused: too many people marked your emails as spam.",
    ifLeft: `Email to your list, your sequences and the email to buyers you brought over wait until ${day} (UTC). Sign-in links and receipts still go out.`,
    fix: { kind: "studio", href: "/studio/email", label: "See what to change" },
  };
}

/**
 * Email to the list stopped by the plan itself (lib/plan.ts, canUse "email"):
 * null when the plan lets it go out, so the pause is read instead.
 */
export function emailStopped(plan: { pro: boolean; renewalUnpaid: boolean; disputed: boolean }): Check | "left-out" | null {
  // A store not on Pro sends no email to a list at all: nothing to check.
  if (!plan.pro) return "left-out";
  const title = "Email to your list";
  if (plan.renewalUnpaid) {
    return {
      id: "email",
      title,
      state: "problem",
      found: "Email to your list is stopped: your plan's last renewal is not paid.",
      ifLeft: "Nothing goes to your list, and your sequences wait, until it is paid. Sign-in links and receipts still go out.",
      fix: { kind: "studio", href: "/studio#billing", label: "Pay the renewal" },
    };
  }
  if (plan.disputed) {
    return {
      id: "email",
      title,
      state: "problem",
      found: "Email to your list is stopped while a payment for your plan is disputed.",
      ifLeft: "Nothing goes to your list, and your sequences wait, until the dispute is closed. Sign-in links and receipts still go out.",
      fix: { kind: "studio", href: "/studio#billing", label: "See your plan" },
    };
  }
  return null;
}

/**
 * Checkouts Stripe refused to open in the last 7 days; null when they could
 * not be read. The count is what lib/checkout-trouble.ts recorded (any
 * Stripe error when opening one, a refusal or Stripe being down), so "ok"
 * says only that none was recorded. readTrouble (lib/checkout-trouble.ts) answers zero today when
 * its store cannot be read, so the screen needs a strict reading of it before
 * an "ok" from here can be shown (next unit).
 */
export function checkoutCheck(trouble: { week: number; last: { message: string } | null } | null): Check {
  const title = "Checkout";
  if (!trouble) return { id: "checkout", title, state: "not-checked", found: "We could not read whether Stripe refused any checkout just now." };
  if (trouble.week <= 0) return { id: "checkout", title, state: "ok", found: "We recorded no checkout that Stripe would not open in the last 7 days." };
  const times = trouble.week === 1 ? "once" : `${trouble.week.toLocaleString("en-US")} times`;
  return {
    id: "checkout",
    title,
    state: "problem",
    // Stripe's own words close the sentence as Stripe wrote them, with no full stop added after the quote.
    found: `Stripe would not open a checkout ${times} in the last 7 days.${trouble.last ? ` The last time it said: "${trouble.last.message}"` : ""}`,
    ifLeft: "A buyer who presses buy gets an error instead of the payment page, and that sale is lost.",
    fix: { kind: "outside", where: "In your Stripe dashboard, look for a notice asking for information and send what it asks for. If there is none, it may have been Stripe failing for a moment, which passes by itself; if it keeps happening, Stripe's words above say what it would not do." },
  };
}

/** The most one use takes of a figure: a studio page is STUDIO_PAGE_UNITS, an API write API_WRITE_UNITS and a page of sales API_SALES_UNITS; anything else one. */
const LARGEST_TAKE: Partial<Record<AllowanceKind, number>> = { studio: STUDIO_PAGE_UNITS, api: Math.max(API_WRITE_UNITS, API_SALES_UNITS) };

/** What stops when a figure is used up, kind by kind. */
function stopsWords(kind: AllowanceKind, reset: string, plansOnSale = true): string {
  if (kind === "studio") return `Your studio rests until it opens again; ${plansOnSale ? "changing or canceling your plan" : "canceling your plan"}, deleting the store and downloading your data still work. ${reset}`;
  return `Until it opens again, what needs it does not run. ${reset}`;
}

/**
 * The plan's figures in the store's window (lib/store-allowance.ts,
 * allowancesUsedStrict; unit 3). A problem when one is used up, or has less
 * left than its next use takes (a studio page takes four), said with its own
 * words (KIND_WORDS) and when it opens again (`reset`, from resetWords); a
 * problem too when confirmations to addresses nobody has shown yet are past
 * their share of the access emails (askedCeiling), which stops only them.
 * Fine otherwise, with the most used one; not checked when they could not be
 * read. A figure of zero (not on this plan) is left out. `paying` says
 * whether the store pays for a plan, so the way out is a larger plan or a
 * plan at all; `plansOnSale` (lib/opening.ts) whether either can be had now;
 * `larger` whether a plan above the store's own is sold (lib/larger-plan.ts):
 * a paying store with none above it is offered no plan at all.
 */
export function limitsCheck(readings: { kind: AllowanceKind; used: number; figure: number }[] | null, reset: string, paying: boolean, plansOnSale = true, larger = false): Check {
  const title = "Your plan's limits";
  if (!readings) return { id: "limits", title, state: "not-checked", found: "We could not read how much of your plan's figures is used just now. Try again in a few minutes." };
  // While no plan is on sale this fix is said, not linked (lib/checkup.ts, forBilling).
  const fix: CheckFix | null = paying && !larger ? null : { kind: "studio", href: "/studio#billing", label: paying ? "See a larger plan" : "Start a plan" };
  const counted = readings.filter((r) => r.figure > 0);
  const share = (r: { used: number; figure: number }) => r.used / r.figure;
  const out = (r: { kind: AllowanceKind; used: number; figure: number }) => r.figure - r.used < (LARGEST_TAKE[r.kind] ?? 1);
  const full = counted.filter(out).sort((a, b) => share(b) - share(a));
  const n = (x: number) => Math.floor(x).toLocaleString("en-US");
  if (full.length) {
    const [first, ...more] = full;
    const words = KIND_WORDS[first.kind];
    return {
      id: "limits",
      title,
      state: "problem",
      found: `${first.used >= first.figure ? `${words.what} in this period are used: ${n(first.figure)} ${words.many}.` : `${words.what} in this period are almost used: ${n(first.used)} of ${n(first.figure)} ${words.many}, less than the next use takes.`}${more.length ? ` ${more.length === 1 ? "One more figure is" : `${more.length} more figures are`} used up too.` : ""}`,
      ifLeft: stopsWords(first.kind, reset, plansOnSale),
      ...(fix ? { fix } : {}),
    };
  }
  const access = counted.find((r) => r.kind === "transactional");
  if (access && access.used >= askedCeiling(access.figure)) {
    return {
      id: "limits",
      title,
      state: "problem",
      found: "Confirmation emails to new addresses (sign-ups, a waitlist, the affiliate form) are paused: they have used their share of your buyers' access emails.",
      ifLeft: `Nobody new can confirm an address until it opens again. Links your buyers ask for still go out. ${reset}`,
      ...(fix ? { fix } : {}),
    };
  }
  const top = [...counted].sort((a, b) => share(b) - share(a))[0];
  return {
    id: "limits",
    title,
    state: "ok",
    found: top && top.used > 0 ? `Nothing is used up. The most used: ${n(top.used)} of ${n(top.figure)} ${KIND_WORDS[top.kind].many}.` : "Nothing is used up.",
  };
}

/** A dispute as the checkup reads it from the creator's Stripe account: its status, when its answer is due (seconds) and whether that is past. */
export type OpenDispute = { status: string; dueBy: number | null; pastDue: boolean };

/**
 * Stripe's dispute statuses (docs.stripe.com/api/disputes/object, status, read
 * 1 November 2026): those waiting for the creator's answer, those with the
 * bank, and those closed. Any other is unknown, and stops the line from
 * saying "fine".
 */
const NEEDS_ANSWER = new Set(["needs_response", "warning_needs_response", "appeal_needs_response"]);
const WITH_THE_BANK = new Set(["under_review", "warning_under_review", "appeal_under_review"]);
const CLOSED = new Set(["won", "lost", "warning_closed", "prevented"]);
export const KNOWN_DISPUTE_STATUSES: ReadonlySet<string> = new Set([...NEEDS_ANSWER, ...WITH_THE_BANK, ...CLOSED]);

/**
 * Disputes on the creator's Stripe account (lib/checkup.ts, readDisputes;
 * unit 4): a problem while one waits for an answer, with the first due date
 * still ahead and how many are past theirs; fine when none does, saying how
 * many are with the bank; not checked when they could not be read, when one
 * has a status this does not know, or when not all of them were read
 * (`complete` false) and none read needs an answer ("at least" when some do).
 */
export function disputesCheck(read: { disputes: OpenDispute[]; complete: boolean } | null, now = Date.now()): Check {
  const title = "Disputes";
  if (!read) return { id: "disputes", title, state: "not-checked", found: "We could not ask Stripe about disputes just now. Try again in a few minutes." };
  if (read.disputes.some((d) => !KNOWN_DISPUTE_STATUSES.has(d.status))) {
    return { id: "disputes", title, state: "not-checked", found: "Stripe answered with a dispute we cannot read. Your Stripe Dashboard lists them all." };
  }
  const waiting = read.disputes.filter((d) => NEEDS_ANSWER.has(d.status));
  const withBank = read.disputes.filter((d) => WITH_THE_BANK.has(d.status)).length;
  if (waiting.length) {
    const late = waiting.filter((d) => d.pastDue || (d.dueBy !== null && d.dueBy * 1000 <= now)).length;
    const due = waiting.filter((d) => !d.pastDue).map((d) => d.dueBy).filter((t): t is number => typeof t === "number" && Number.isFinite(t) && t * 1000 > now).sort((a, b) => a - b)[0];
    const day = due ? new Date(due * 1000).toLocaleDateString("en-US", { month: "long", day: "numeric", timeZone: "UTC" }) : null;
    const many = waiting.length === 1 ? "one dispute is waiting" : `${waiting.length.toLocaleString("en-US")} disputes are waiting`;
    const count = read.complete ? many : `at least ${many}`;
    const lateWords = late ? ` ${late === 1 ? "One is past its" : `${late.toLocaleString("en-US")} are past their`} due date.` : "";
    return {
      id: "disputes",
      title,
      state: "problem",
      found: `${count.charAt(0).toUpperCase()}${count.slice(1)} for your answer on your Stripe account.${day ? ` The next is due on ${day} (UTC).` : ""}${lateWords}`,
      // Stripe's own words (docs.stripe.com/disputes/responding, read 1 November 2026): "If you don't respond before
      // the deadline, you automatically lose the dispute and can't retrieve the disputed funds."
      ifLeft: "A dispute not answered by its due date is lost, and the disputed money cannot be won back.",
      fix: { kind: "outside", where: "On the Disputes page of your Stripe Dashboard, answer each one before its due date. To look at the purchase first, use the \"Review one disputed purchase\" page in your studio." },
    };
  }
  if (!read.complete) return { id: "disputes", title, state: "not-checked", found: "There are more disputes than we read here. Your Stripe Dashboard lists them all." };
  return {
    id: "disputes",
    title,
    state: "ok",
    found: withBank
      ? `No dispute is waiting for your answer. ${withBank === 1 ? "One is" : `${withBank} are`} with the buyer's bank for a decision.`
      : "No dispute is waiting for your answer on your Stripe account.",
  };
}

/** A part with no reader yet: always "not checked", never fine. */
export function notCheckedYet(id: "limits"): Check {
  return { id, title: "Your plan's limits", state: "not-checked", found: "Not checked here yet. Each limit is shown where you use it." };
}


/** The checks in the order shown: problems first, then what could not be checked, then what is fine; each group in a fixed order. */
const ORDER: CheckId[] = ["stripe", "checkout", "domain", "email", "limits", "disputes"];
const RANK: Record<CheckState, number> = { problem: 0, "not-checked": 1, ok: 2 };

export function orderChecks(checks: (Check | null)[]): Check[] {
  return checks
    .filter((c): c is Check => c !== null)
    .sort((a, b) => RANK[a.state] - RANK[b.state] || ORDER.indexOf(a.id) - ORDER.indexOf(b.id));
}

/**
 * The one line at the top. Never "everything is fine" while anything was not
 * checked: it says how many were.
 */
export function checkupSummary(checks: Check[]): string {
  const problems = checks.filter((c) => c.state === "problem").length;
  const unchecked = checks.filter((c) => c.state === "not-checked").length;
  const parts: string[] = [];
  if (problems) parts.push(`${problems} ${problems === 1 ? "problem" : "problems"} found`);
  if (unchecked) parts.push(`${unchecked} not checked`);
  if (checks.length === 0) return "Nothing was checked.";
  if (!problems && !unchecked) return "We checked everything listed here and found no problem.";
  if (!problems) return `No problem found in what we checked; ${unchecked} not checked.`;
  return `${parts.join(", ")}.`;
}

/**
 * Audit R18, finding 1 (synthetic): a dispute of a plan payment that Stripe
 * closes as "prevented" (the money went back to the creator before a
 * chargeback, as lib/plan-refund-rules.ts RETURNED and lib/checkup-rules.ts
 * CLOSED already read it) or as the legacy "charge_refunded" (the charge was
 * refunded) was read by disputeStatusOf() as "open" for ever:
 *
 *   - the store stayed paused (checkout, list emails, AI, uploads, video)
 *     with no end, long after the period the payment covered;
 *   - the daily job kept it as "open:<store>" and re-read it every day, so
 *     MAX_REREADS stuck ones took every re-read slot and an older dispute
 *     really decided later was never read again.
 *
 * Expected: both read as "lost" (the money went back), so they pause to the
 * end of the period the payment covered and are remembered as final. Every
 * other status reads exactly as before; a status Stripe does not document
 * still reads as open (unknown is never "closed" or "won").
 */
import { isPaidUp } from "@/lib/billing";
import { claimHandle, ensureStatsId, recordPlanDispute, setSubscription, storeForEmail, storeRef } from "@/lib/store";
import { costPauseCode } from "@/lib/plan-standing";
import { disputeStatusOf } from "@/lib/plan-dispute-rules";
import { MAX_REREADS, SEEN_KEY, syncPlanDisputes } from "@/lib/plan-disputes";
import { paidPeriod } from "./billing-period-fixture";
import { store as redis } from "./redis-stub";
import { done, is, part } from "./check";

process.env.STRIPE_SECRET_KEY = "sk_test_plan_dispute_closed_only";

const DAY = 86_400;
const NOW = Math.floor(Date.now() / 1000);
const owner = "plan-dispute-closed@example.com";
const handle = "plan-dispute-closed-shop";
const SUB = "sub_PlanDisputeClosed01";
let pages: { data: Record<string, unknown>[]; has_more: boolean }[] = [];
let byId: Record<string, Record<string, unknown>> = {};
const asked: string[] = [];

globalThis.fetch = (async (input: string | URL | Request, init?: RequestInit) => {
  const url = new URL(String(input));
  const method = init?.method ?? "GET";
  if (url.hostname === "api.stripe.com") {
    asked.push(`${method} ${url.pathname}`);
    if (method !== "GET") return new Response("{}", { status: 400 });
    if (url.pathname === "/v1/disputes") return Response.json(pages[0] ?? { data: [], has_more: false });
    if (url.pathname.startsWith("/v1/disputes/")) {
      const id = url.pathname.split("/").pop() ?? "";
      return byId[id] ? Response.json(byId[id]) : new Response(JSON.stringify({ error: { message: "missing" } }), { status: 404 });
    }
    if (url.pathname === `/v1/subscriptions/${SUB}`) return Response.json({ id: SUB, metadata: { store: handle }, customer: "cus_PlanDisputeClosed01" });
  }
  return new Response("{}", { status: 404 });
}) as typeof fetch;

function dispute(id: string, status: string): Record<string, unknown> {
  return {
    id,
    object: "dispute",
    status,
    created: NOW - DAY,
    charge: { id: `ch_${id.slice(3)}`, invoice: { id: `in_${id.slice(3)}`, subscription: SUB, lines: { data: [{ period: { start: NOW - 10 * DAY, end: NOW + 20 * DAY } }] } } },
  };
}

async function setup() {
  redis.clear();
  asked.length = 0;
  byId = {};
  pages = [];
  await claimHandle(owner, handle, "Plan dispute closed shop", "");
  await ensureStatsId(owner);
  await setSubscription(owner, { customerId: "cus_PlanDisputeClosed01", subscriptionId: SUB, active: true, tier: "pro", cycle: "month", period: paidPeriod() });
}

async function seen(): Promise<Map<string, string>> {
  const raw = await redis.run(["HGETALL", SEEN_KEY]);
  const out = new Map<string, string>();
  if (Array.isArray(raw)) for (let i = 0; i + 1 < raw.length; i += 2) out.set(String(raw[i]), String(raw[i + 1]));
  else if (raw && typeof raw === "object") for (const [key, value] of Object.entries(raw)) out.set(key, String(value));
  return out;
}

async function main() {
  part("Stripe's closed statuses are not read as still open");
  is("prevented reads as lost (the money went back)", disputeStatusOf("prevented"), "lost");
  is("charge_refunded reads as lost (the charge was refunded)", disputeStatusOf("charge_refunded"), "lost");
  is("won is unchanged", disputeStatusOf("won"), "won");
  is("warning_closed is unchanged", disputeStatusOf("warning_closed"), "won");
  is("lost is unchanged", disputeStatusOf("lost"), "lost");
  for (const status of ["needs_response", "under_review", "warning_needs_response", "warning_under_review"]) {
    is(`${status} is still open`, disputeStatusOf(status), "open");
  }
  for (const status of ["something_new", "Prevented", "PREVENTED", " prevented", "charge_refunded ", "", null, undefined, 0, ["prevented"], { status: "prevented" }]) {
    is(`${JSON.stringify(status) ?? "undefined"} is unknown, still open (never closed or won)`, disputeStatusOf(status), "open");
  }

  for (const status of ["prevented", "charge_refunded"]) {
    part(`A plan dispute listed as ${status}`);
    await setup();
    const id = `du_Closed${status.replace(/_/g, "")}`;
    pages = [{ data: [dispute(id, status)], has_more: false }];
    const read = await syncPlanDisputes(Date.now() + 10_000, NOW);
    is("recorded once, nothing failed", [read.recorded, read.failed, read.complete], [1, 0, true]);
    const after = (await storeForEmail(owner))!;
    is("written as lost, with the period it covered", after.planDisputes, [{ id, status: "lost", at: NOW - DAY, coversUntil: NOW + 20 * DAY }]);
    is("paused while the period it paid for runs", costPauseCode(after, NOW) !== null, true);
    is("checkout closed while the period it paid for runs", isPaidUp(after), false);
    for (const later of [NOW + 21 * DAY, NOW + 400 * DAY]) {
      is(`no pause ${Math.round((later - NOW) / DAY)} days later`, costPauseCode(after, later), null);
    }
    is("remembered as final, not open", (await seen()).get(id), "final");
    asked.length = 0;
    pages = [{ data: [], has_more: false }];
    await syncPlanDisputes(Date.now() + 10_000, NOW);
    is("not read again by id the next day", asked.filter((line) => line.startsWith("GET /v1/disputes/")), []);
  }

  for (const status of ["prevented", "charge_refunded"]) {
    part(`An open plan dispute past the list window, re-read as ${status}`);
    await setup();
    const id = `du_Stale${status.replace(/_/g, "")}`;
    const before = (await storeForEmail(owner))!;
    await recordPlanDispute(storeRef(before), { id, status: "open", at: NOW - 200 * DAY, coversUntil: NOW - 170 * DAY }, NOW);
    await redis.run(["HSET", SEEN_KEY, id, `open:${before.sid}`]);
    byId = { [id]: { id, object: "dispute", status, created: NOW - 200 * DAY } };
    const read = await syncPlanDisputes(Date.now() + 10_000, NOW);
    is("re-read and recorded", [read.reread, read.recorded, read.failed], [1, 1, 0]);
    const after = (await storeForEmail(owner))!;
    is("written as lost, keeping the period first read", after.planDisputes, [{ id, status: "lost", at: NOW - 200 * DAY, coversUntil: NOW - 170 * DAY }]);
    is("its period long over: nothing paused", costPauseCode(after, NOW), null);
    is("checkout open again", isPaidUp(after), true);
    is("its re-read slot is freed (final)", (await seen()).get(id), "final");
  }

  part("Stuck ones never hold every re-read slot");
  {
    await setup();
    const store = (await storeForEmail(owner))!;
    // MAX_REREADS old disputes closed as prevented, then one older dispute the bank decided for us.
    const stuck = Array.from({ length: MAX_REREADS }, (_, i) => `du_Stuck${String(i).padStart(3, "0")}`);
    const late = "du_StuckWonLater";
    for (const id of [...stuck, late]) {
      await redis.run(["HSET", SEEN_KEY, id, `open:${store.sid}`]);
      byId[id] = { id, object: "dispute", status: id === late ? "won" : "prevented", created: NOW - 200 * DAY };
    }
    await recordPlanDispute(storeRef(store), { id: late, status: "open", at: NOW - 200 * DAY, coversUntil: NOW - 170 * DAY }, NOW);
    for (let run = 0; run < 3; run += 1) await syncPlanDisputes(Date.now() + 10_000, NOW);
    const after = await seen();
    is("no stuck one is still open", stuck.filter((id) => after.get(id) !== "final"), []);
    is("the later win is read in a following run", after.get(late), "final");
    const lifted = (await storeForEmail(owner))!;
    // Written as won, it no longer pauses, so withPlanDispute may drop it first past PLAN_DISPUTES_KEPT: never kept as open.
    is("and no longer kept as open on the store", lifted.planDisputes?.some((kept) => kept.id === late && kept.status === "open"), false);
    asked.length = 0;
    const next = await syncPlanDisputes(Date.now() + 10_000, NOW);
    is("the run after asks Stripe no dispute by id and is complete", [asked.filter((line) => line.startsWith("GET /v1/disputes/")).length, next.complete], [0, true]);
  }

  part("Controls: an open dispute and an undocumented status stay open");
  for (const status of ["needs_response", "something_new"]) {
    await setup();
    const id = `du_Ctrl${status.replace(/_/g, "")}`;
    pages = [{ data: [dispute(id, status)], has_more: false }];
    await syncPlanDisputes(Date.now() + 10_000, NOW);
    const after = (await storeForEmail(owner))!;
    is(`${status}: written as open`, after.planDisputes?.[0]?.status, "open");
    is(`${status}: still paused past the period`, costPauseCode(after, NOW + 400 * DAY) !== null, true);
    is(`${status}: kept for a re-read`, (await seen()).get(id), `open:${after.sid}`);
  }

  done();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

